import itertools,json
jobs="ABCDE"
slot=dict(zip(jobs,[[4,8,0,2,0],[6,4,5,0,5],[2,6,4,6,0],[8,7,9,6,0],[3,3,1,6,5]]))
trans=dict(zip(jobs,[[0,1,1,3,1],[5,0,2,4,2],[3,1,0,0,3],[5,4,4,0,5],[5,0,3,4,0]]))
def nominal(r):
    return sum(slot[j][i] for i,j in enumerate(r))+sum(trans[a][jobs.index(b)] for a,b in zip(r,r[1:]))
def incident(r,k):
    p={j:r.index(j)+1 for j in jobs}
    if k=="rain":
        return None if p["E"]==2 or p["D"]==5 else nominal(r)+6*max(0,p["A"]-2)
    if k=="road":
        return None if p["B"]==5 or p["D"]==1 else nominal(r)+8*max(0,p["C"]-3)
    return None if p["D"]==4 or p["C"]==1 else nominal(r)+5*max(0,p["E"]-1)
rosters=["".join(p) for p in itertools.permutations(jobs) if p.index("A")<p.index("D")]
results=[]
for r in rosters:
    neighbors=[(r,0)]
    for i,j in itertools.combinations(range(5),2):
        q=list(r)
        q[i],q[j]=q[j],q[i]
        q="".join(q)
        if q.index("A")<q.index("D"):
            neighbors.append((q,4))
    best={}
    for k in ["rain","road","lift"]:
        choices=[(incident(q,k)+fee,q) for q,fee in neighbors if incident(q,k) is not None]
        if choices: best[k]=min(choices)
    if len(best)==3:
        results.append((nominal(r)+max(v[0] for v in best.values()),r,best))
results.sort()
score,r,best=results[0]
out=dict(roster=r,score=score,repairs={k:v[1] for k,v in best.items()},repair_costs={k:v[0] for k,v in best.items()},feasible_count=len(results),next_score=min(s for s,_,_ in results if s>score))
payload=json.dumps(out,separators=(",",":"))
decoded=json.loads(payload)
# Independent full final-permutation enumeration, positional-distance exchange criterion.
independent=[]
for pub in rosters:
    costs={}
    for k in ("rain","road","lift"):
        options=[]
        for fin in rosters:
            distance=sum(a!=b for a,b in zip(pub,fin))
            if distance not in (0,2): continue
            a,b,c,d,e=[fin.index(x)+1 for x in jobs]
            if (k=="rain" and (e==2 or d==5)) or (k=="road" and (b==5 or d==1)) or (k=="lift" and (d==4 or c==1)): continue
            base=sum(slot[fin[i]][i] for i in range(5))
            base+=sum(trans[fin[i]][ord(fin[i+1])-65] for i in range(4))
            penalty={"rain":6*max(a-2,0),"road":8*max(c-3,0),"lift":5*max(e-1,0)}[k]
            options.append((base+penalty+4*(distance==2),fin))
        if options: costs[k]=min(options)[0]
    if len(costs)==3: independent.append((nominal(pub)+max(costs.values()),pub,costs))
assert len(independent)==decoded["feasible_count"]
assert min(s for s,_,_ in independent)==decoded["score"]
assert min(s for s,_,_ in independent if s>decoded["score"])==decoded["next_score"]
row=next(x for x in independent if x[1]==decoded["roster"])
assert row[0]==decoded["score"] and row[2]==decoded["repair_costs"]
for k,fin in decoded["repairs"].items():
    assert fin in rosters
    dist=sum(a!=b for a,b in zip(r,fin))
    assert dist in (0,2)
    assert incident(fin,k)+4*(dist==2)==decoded["repair_costs"][k]
print(payload)
print("Verified all fields against independent full-permutation enumeration.")
print("Published nominal:",nominal(r))

