import itertools,json
jobs="ABCDE"; pub="ACEBD"
slot=[[4,8,0,2,0],[6,4,5,0,5],[2,6,4,6,0],[8,7,9,6,0],[3,3,1,6,5]]
trans=[[0,1,1,3,1],[5,0,2,4,2],[3,1,0,0,3],[5,4,4,0,5],[5,0,3,4,0]]
def distance(r):
    mapping=[pub.index(j) for j in r]
    seen=set(); cycles=0
    for i in range(5):
        if i not in seen:
            cycles+=1
            while i not in seen:
                seen.add(i); i=mapping[i]
    return 5-cycles
def legal(r):
    return r.index("A")<r.index("D") and r.index("E") not in (1,2) and r.index("D")!=4
def cost(r,d):
    ids=[jobs.index(j) for j in r]
    return sum(slot[j][i] for i,j in enumerate(ids))+sum(trans[a][b] for a,b in zip(ids,ids[1:]))+6*max(0,r.index("A")-1)+4*d+5*(d==2)
groups={d:[] for d in range(3)}
for p in itertools.permutations(jobs):
    r="".join(p); d=distance(r)
    if d<=2 and legal(r): groups[d].append((cost(r,d),r))
best=min(v for g in groups.values() for v in g)
out={"roster":best[1],"score":best[0],"best_by_swaps":{str(d):min(g)[0] if g else None for d,g in groups.items()},"feasible_by_swaps":{str(d):len(g) for d,g in groups.items()}}
# Independent breadth-first exchange generation checks minimum distances and counts.
depths={pub:0}; frontier={pub}
for d in (1,2):
    nxt=set()
    for r in frontier:
        for i,j in itertools.combinations(range(5),2):
            p=list(r); p[i],p[j]=p[j],p[i]; p="".join(p)
            if p not in depths: nxt.add(p)
    for r in nxt: depths[r]=d
    frontier=nxt
payload=json.dumps(out,separators=(",",":"))
got=json.loads(payload)
for d in range(3):
    pool=[r for r,n in depths.items() if n==d and legal(r)]
    assert len(pool)==got["feasible_by_swaps"][str(d)]
    assert (min(cost(r,d) for r in pool) if pool else None)==got["best_by_swaps"][str(d)]
    assert set(pool)==set(r for _,r in groups[d])
assert legal(got["roster"])
assert cost(got["roster"],depths[got["roster"]])==got["score"]==min(v for v in got["best_by_swaps"].values() if v is not None)
print(payload)
print("Verified via full permutation enumeration and independent exchange BFS.")

